// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@solidstate/contracts/security/pausable/PausableInternal.sol";
import "@solidstate/contracts/security/reentrancy_guard/ReentrancyGuard.sol";

import "../libraries/LibData.sol";
import "../interfaces/IChallengePoolHandler.sol";
import "../libraries/LibPrice.sol";
import "../libraries/LibTransfer.sol";
import "../libraries/LibPool.sol";
import "../libraries/LibTournament.sol";

import "../utils/Helpers.sol";
import "../utils/Errors.sol";

import "./TopicRegistry.sol";

import "../diamond/interfaces/SoccersmRoles.sol";
import "../utils/ChallengePoolHelpers.sol";
import "../interfaces/ICommunity.sol";
import "../interfaces/ITournament.sol";

contract ChallengePoolHandler is
    IChallengePoolHandler,
    SoccersmRoles,
    Helpers,
    ChallengePoolHelpers,
    PausableInternal,
    ReentrancyGuard
{
    function createChallenge(
        ChallengeEvent[] calldata _events,
        bytes[] calldata _options,
        address _stakeToken,
        bytes calldata _prediction,
        uint256 _quantity,
        uint256 _basePrice,
        address _paymaster,
        bytes32 _communityId,
        ChallengeType _cType
    )
        external
        override
        whenNotPaused
        nonZero(_quantity)
        nonZero(_basePrice)
        positiveAddress(_stakeToken)
        supportedToken(_stakeToken)
        validStake(_basePrice)
        validPrediction(_prediction)
    {
        CPStore storage s = CPStorage.load();

        if (_cType == ChallengeType.community) {
            if (_communityId == bytes32(0)) {
                revert ICommunity.CommunityChallengeRequiresCommunity();
            }
            CommunityStore storage cs = CommunityStorage.load();
            ICommunity.Community storage community = cs.communities[
                _communityId
            ];
            if (community.owner == address(0)) {
                revert ICommunity.CommunityDoesNotExist(_communityId);
            }
            if (community.banned) {
                revert ICommunity.CommunityIsBanned();
            }
            if (
                !cs.isAdmin[_communityId][msg.sender] &&
                community.owner != msg.sender
            ) {
                revert ICommunity.NotCommunityOwnerOrAdmin(
                    _communityId,
                    msg.sender
                );
            }
        }

        if (_events.length < 1) {
            revert InvalidEventLength();
        }
        if (_events.length > s.maxEventsPerPool) {
            revert InvalidOptionsLength();
        }
        if (_options.length > s.maxOptionsPerPool) {
            revert InvalidOptionsLength();
        }

        TRStore storage t = TRStorage.load();
        bytes[] memory poolOptions;
        bool multi;
        if (_options.length == 0) {
            multi = false;
            poolOptions = HelpersLib.yesNoOptions();
        } else {
            multi = true;
            if (_options.length < 2) {
                revert InvalidOptionsLength();
            }
            if (_events.length > 1) {
                revert InvalidEventLength();
            }
            poolOptions = _options;
            if (_cType == ChallengeType.standard) {
                LibPool._validateOptions(t, _events[0], poolOptions);
            }

            if (_cType == ChallengeType.tournament) {
                TournamentStore storage ts = TournamentStorage.load();
                if (_communityId == bytes32(0)) {
                    revert ITournament.TournamentChallengeRequiresId();
                }
                LibTournament._validateTournamentOptions(
                    ts,
                    _communityId,
                    poolOptions
                );
            }
        }

        bool predictionExists = false;
        for (uint i = 0; i < poolOptions.length; i++) {
            if (
                HelpersLib.compareBytes(HelpersLib.emptyBytes, poolOptions[i])
            ) {
                revert InvalidPoolOption();
            }
            if (HelpersLib.compareBytes(_prediction, poolOptions[i])) {
                predictionExists = true;
            }
            s
            .optionSupply[s.challengeId][keccak256(poolOptions[i])]
                .exists = true;
        }
        if (!predictionExists) {
            revert InvalidPrediction();
        }
        uint256 maturity = HelpersLib.largestInt;
        for (uint i = 0; i < _events.length; i++) {
            if (_events[i].maturity < (block.timestamp + s.minMaturityPeriod)) {
                revert InvalidEventMaturity();
            }

            if (maturity > _events[i].maturity) {
                maturity = _events[i].maturity;
            }

            if (_cType == ChallengeType.standard) {
                if (
                    t.registry[_events[i].topicId].state ==
                    ITopicRegistry.TopicState.disabled
                ) {
                    revert InvalidEventTopic();
                }

                LibPool._validateEvent(t, _events[i]);
            }
            if (_cType == ChallengeType.tournament) {
                TournamentStore storage ts = TournamentStorage.load();
                bool eventExists = LibTournament._validateTournamentEvent(
                    ts,
                    _communityId,
                    _events[i]
                );
                if (!eventExists) {
                    revert ITournament.TournamentEventNotFound();
                }
            }
        }
        uint256 totalAmount = _basePrice * _quantity;
        uint256 fee = LibPrice._computeCreateFee(totalAmount);
        LibPool._recordFee(_stakeToken, fee);

        LibPool._initPool(
            _stakeToken,
            _events,
            poolOptions,
            multi,
            _prediction,
            maturity,
            _basePrice,
            _quantity,
            totalAmount,
            fee,
            msg.sender,
            _communityId,
            _cType
        );
        LibTransfer._depositOrPaymaster(
            _paymaster,
            _stakeToken,
            totalAmount + fee,
            msg.sender
        );
    }

    function stake(
        uint256 _challengeId,
        bytes calldata _prediction,
        uint256 _quantity,
        address _paymaster
    )
        external
        override
        whenNotPaused
        validChallenge(_challengeId)
        validPrediction(_prediction)
        nonZero(_quantity)
        poolInState(_challengeId, ChallengeState.open)
    {
        CPStore storage s = CPStorage.load();

        uint256 currentPrice = s.challenges[_challengeId].basePrice;

        if (!s.optionSupply[_challengeId][keccak256(_prediction)].exists) {
            revert InvalidPrediction();
        }
        uint256 totalAmount = currentPrice * _quantity;
        uint256 fee = LibPrice._computeStakeFee(totalAmount);
        uint256 rewardPoints = LibPrice._stakeRewardPoints(
            _quantity,
            s.challenges[_challengeId].createdAt,
            s.challenges[_challengeId].maturity
        );
        LibPool._incrementSupply(
            s,
            _challengeId,
            _prediction,
            _quantity,
            totalAmount,
            rewardPoints,
            msg.sender
        );
        LibPool._recordFee(s.challenges[_challengeId].stakeToken, fee);
        LibTransfer._depositOrPaymaster(
            _paymaster,
            s.challenges[_challengeId].stakeToken,
            fee + totalAmount,
            msg.sender
        );
        LibTransfer._stakeAirDrop(
            _paymaster,
            s.challenges[_challengeId].stakeToken,
            msg.sender,
            s.challenges[_challengeId].maturity
        );
        emit Stake(
            _challengeId,
            msg.sender,
            _prediction,
            _quantity,
            currentPrice,
            totalAmount,
            fee,
            rewardPoints
        );
    }

    function earlyWithdraw(
        uint256 _challengeId,
        bytes calldata _prediction,
        uint256 _quantity,
        uint256 _deadline
    )
        external
        override
        whenNotPaused
        nonReentrant
        validChallenge(_challengeId)
        validPrediction(_prediction)
        nonZero(_quantity)
        nonZero(_deadline)
        poolInState(_challengeId, ChallengeState.open)
    {
        revert NotImplemented();
        // CPStore storage s = CPStorage.load();
        // if (_deadline < block.timestamp) {
        //     revert DeadlineExceeded();
        // }
        // if (!s.optionSupply[_challengeId][keccak256(_prediction)].exists) {
        //     revert InvalidPrediction();
        // }
        // IChallengePoolHandler.PlayerSupply storage playerOptionSupply = s
        //     .playerOptionSupply[_challengeId][msg.sender][
        //         keccak256(_prediction)
        //     ];
        // if (playerOptionSupply.stakes < _quantity) {
        //     revert IChallengePoolCommon.InsufficientStakes(
        //         _quantity,
        //         playerOptionSupply.stakes
        //     );
        // }
        // uint256 basePrice = s.challenges[_challengeId].basePrice;
        // uint256 penalty = LibPrice._penalty(
        //     basePrice,
        //     s.challenges[_challengeId].createdAt,
        //     s.challenges[_challengeId].maturity
        // );
        // uint256 currentPrice = basePrice - penalty;
        // uint256 totalAmount = basePrice * _quantity;
        // uint256 fee = LibPrice._computeEarlyWithdrawFee(totalAmount);
        // uint256 rewardPoints = LibPrice._earlyWithdrawRewardPoints(
        //     playerOptionSupply.rewards,
        //     playerOptionSupply.stakes,
        //     _quantity
        // );
        // LibPool._decrementSupply(
        //     s,
        //     _challengeId,
        //     _prediction,
        //     _quantity,
        //     totalAmount,
        //     rewardPoints
        // );
        // LibPool._recordFee(s.challenges[_challengeId].stakeToken, fee);
        // LibTransfer._receive(s.challenges[_challengeId].stakeToken, fee);

        // LibTransfer._send(
        //     s.challenges[_challengeId].stakeToken,
        //     totalAmount,
        //     msg.sender
        // );
        // emit Withdraw(
        //     _challengeId,
        //     msg.sender,
        //     _prediction,
        //     _quantity,
        //     currentPrice,
        //     penalty,
        //     totalAmount,
        //     fee,
        //     rewardPoints
        // );
    }

    function withdraw(
        uint256 _challengeId
    )
        external
        override
        whenNotPaused
        nonReentrant
        validChallenge(_challengeId)
    {
        LibPool._withdraw(_challengeId, msg.sender);
    }

    function bulkWithdraw(uint256[] calldata _challengeIds) external override {
        for (uint i = 0; i < _challengeIds.length; i++) {
            if (_challengeIds[i] >= CPStorage.load().challengeId) {
                revert IChallengePoolCommon.InvalidChallenge();
            }
            LibPool._withdraw(_challengeIds[i], msg.sender);
        }
    }

    function evaluate(
        uint256 _challengeId
    )
        external
        override
        whenNotPaused
        validChallenge(_challengeId)
        poolInState(_challengeId, ChallengeState.matured)
    {
        TRStore storage t = TRStorage.load();
        CPStore storage s = CPStorage.load();
        Challenge storage c = s.challenges[_challengeId];
        c.state = ChallengeState.evaluated;
        bytes memory result = HelpersLib.emptyBytes;
        if (!c.multi) {
            bool allCorrect = true;
            for (uint i = 0; i < c.events.length; i++) {
                if (c.events[i].maturity > block.timestamp) {
                    revert InvalidEventMaturity();
                }
                if (
                    HelpersLib.compareBytes(
                        HelpersLib.no,
                        LibPool._resolveEvent(t, c.events[i], c.options)
                    )
                ) {
                    allCorrect = false;
                    break;
                }
            }
            if (allCorrect) {
                result = HelpersLib.yes;
            } else {
                result = HelpersLib.no;
            }
        } else {
            result = LibPool._resolveEvent(t, c.events[0], c.options);
        }
        c.outcome = result;
        c.lastOutcomeSet = block.timestamp;

        emit EvaluateChallenge(
            _challengeId,
            msg.sender,
            ChallengeState.evaluated,
            result
        );
    }

    function close(
        uint256 _challengeId
    ) external override whenNotPaused validChallenge(_challengeId) {
        CPStore storage s = CPStorage.load();
        Challenge storage c = s.challenges[_challengeId];
        if (HelpersLib.compareBytes(HelpersLib.emptyBytes, c.outcome)) {
            revert InvalidOutcome();
        }
        if (
            c.state != ChallengeState.settled &&
            c.state != ChallengeState.evaluated
        ) {
            revert ActionNotAllowedForState(c.state);
        }
        if (block.timestamp - c.lastOutcomeSet < s.disputePeriod) {
            revert DisputePeriod();
        }
        c.state = ChallengeState.closed;
        emit CloseChallenge(
            _challengeId,
            msg.sender,
            ChallengeState.closed,
            c.outcome
        );
    }
}

contracts/modules/ChallengePoolManager.s.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";

import "@solidstate/contracts/security/reentrancy_guard/ReentrancyGuard.sol";
import "../libraries/LibData.sol";
import "../libraries/LibTransfer.sol";
import "../interfaces/IChallengePoolManager.sol";
import "../utils/Helpers.sol";
import "../diamond/interfaces/SoccersmRoles.sol";
contract ChallengePoolManager is
    IChallengePoolManager,
    SoccersmRoles,
    Helpers,
    ReentrancyGuard
{
    function setFeeAddress(
        address _feeAddress
    ) external override onlyPoolManager positiveAddress(_feeAddress) {
        address oldFeeAddress = CPStorage.load().feeAddress;
        CPStorage.load().feeAddress = _feeAddress;
        emit SetFeeAddress(msg.sender, oldFeeAddress, _feeAddress);
    }

    function setMinMaturityPeriod(
        uint256 _minMaturityPeriod
    ) external override onlyPoolManager nonZero(_minMaturityPeriod) {
        uint256 oldMinMaturityPeriod = CPStorage.load().minMaturityPeriod;
        CPStorage.load().minMaturityPeriod = _minMaturityPeriod;
        emit SetMinMaturityPeriod(
            msg.sender,
            oldMinMaturityPeriod,
            _minMaturityPeriod
        );
    }

    function setCreatePoolFee(
        uint256 _createPoolFee
    ) external override onlyPoolManager nonZero(_createPoolFee) {
        uint256 oldCreatePoolFee = CPStorage.load().createPoolFee;
        CPStorage.load().createPoolFee = _createPoolFee;
        emit SetCreatePoolFee(msg.sender, oldCreatePoolFee, _createPoolFee);
    }

    function setStakeFee(
        uint256 _stakeFee
    ) external override onlyPoolManager nonZero(_stakeFee) {
        uint256 oldStakeFee = CPStorage.load().stakeFee;
        CPStorage.load().stakeFee = _stakeFee;
        emit SetStakeFee(msg.sender, oldStakeFee, _stakeFee);
    }

    function setEarlyWithdrawFee(
        uint256 _earlyWithdrawFee
    ) external override onlyPoolManager nonZero(_earlyWithdrawFee) {
        uint256 oldEarlyWithdrawFee = CPStorage.load().earlyWithdrawFee;
        CPStorage.load().earlyWithdrawFee = _earlyWithdrawFee;
        emit SetEarlyWithdrawFee(
            msg.sender,
            oldEarlyWithdrawFee,
            _earlyWithdrawFee
        );
    }

    function setMaxOptionsPerPool(
        uint256 _maxOptionsPerPool
    ) external override onlyPoolManager nonZero(_maxOptionsPerPool) {
        uint256 oldMaxOptionsPerPool = CPStorage.load().maxOptionsPerPool;
        CPStorage.load().maxOptionsPerPool = _maxOptionsPerPool;
        emit SetMaxOptionsPerPool(
            msg.sender,
            oldMaxOptionsPerPool,
            _maxOptionsPerPool
        );
    }

    function setMaxEventsPerPool(
        uint256 _maxEventsPerPool
    ) external override onlyPoolManager nonZero(_maxEventsPerPool) {
        uint256 oldMaxEventsPerPool = CPStorage.load().maxEventsPerPool;
        CPStorage.load().maxEventsPerPool = _maxEventsPerPool;
        emit SetMaxEventsPerPool(
            msg.sender,
            oldMaxEventsPerPool,
            _maxEventsPerPool
        );
    }

    function setMinStakeAmount(
        uint256 _minStakeAmount
    ) external override onlyPoolManager nonZero(_minStakeAmount) {
        uint256 oldMinStakeAmount = CPStorage.load().minStakeAmount;
        CPStorage.load().minStakeAmount = _minStakeAmount;
        emit SetMinStakeAmount(msg.sender, oldMinStakeAmount, _minStakeAmount);
    }

    function addStakeToken(
        address _stakeToken
    ) external override onlyPoolManager positiveAddress(_stakeToken) {
        CPStore storage c = CPStorage.load();
        require(!c.stakeTokens[_stakeToken].active, "stake token is active");
        c.stakeTokens[_stakeToken] = StakeToken(_stakeToken, 0, true);
        emit StakeTokenAdded(msg.sender, _stakeToken, true);
    }

    function removeStakeToken(
        address _stakeToken
    ) external override onlyPoolManager positiveAddress(_stakeToken) {
        CPStore storage c = CPStorage.load();
        StakeToken storage st = c.stakeTokens[_stakeToken];
        require(st.active, "stake token is not active");
        st.active = false;
        emit StakeTokenRemoved(msg.sender, _stakeToken, false);
    }

    function setDisputePeriod(
        uint256 _disputePeriod
    ) external override onlyPoolManager nonZero(_disputePeriod) {
        uint256 oldDisputePeriod = CPStorage.load().disputePeriod;
        CPStorage.load().disputePeriod = _disputePeriod;
        emit SetDisputePeriod(msg.sender, oldDisputePeriod, _disputePeriod);
    }

    function setDisputeStake(
        uint256 _disputeStake
    ) external override onlyPoolManager nonZero(_disputeStake) {
        uint256 oldDisputeStake = CPStorage.load().disputeStake;
        CPStorage.load().disputeStake = _disputeStake;
        emit SetDisputeStake(msg.sender, oldDisputeStake, _disputeStake);
    }

    function withdrawFee(
        address _stakeToken
    ) external override nonReentrant onlyAdmin {
        CPStore storage c = CPStorage.load();
        StakeToken storage st = c.stakeTokens[_stakeToken];
        require(st.accumulatedFee > 0, "no fee to extra");
        uint256 accumulatedFee = st.accumulatedFee;
        st.accumulatedFee = 0;
        LibTransfer._send(_stakeToken, accumulatedFee, msg.sender);
        emit FeeWithdrawn(msg.sender, _stakeToken, msg.sender, accumulatedFee);
    }

    function feeAddress() external view override returns (address) {
        return CPStorage.load().feeAddress;
    }

    function minMaturityPeriod() external view override returns (uint256) {
        return CPStorage.load().minMaturityPeriod;
    }

    function createPoolFee() external view override returns (uint256) {
        return CPStorage.load().createPoolFee;
    }

    function stakeFee() external view override returns (uint256) {
        return CPStorage.load().stakeFee;
    }

    function earlyWithdrawFee() external view override returns (uint256) {
        return CPStorage.load().earlyWithdrawFee;
    }

    function maxOptionsPerPool() external view override returns (uint256) {
        return CPStorage.load().maxOptionsPerPool;
    }

    function maxEventsPerPool() external view override returns (uint256) {
        return CPStorage.load().maxEventsPerPool;
    }

    function minStakeAmount() external view override returns (uint256) {
        return CPStorage.load().minStakeAmount;
    }

    function disputePeriod() external view override returns (uint256) {
        return CPStorage.load().disputePeriod;
    }

    function disputeStake() external view override returns (uint256) {
        return CPStorage.load().disputeStake;
    }

    function challengeId() external view override returns (uint256) {
        return CPStorage.load().challengeId;
    }

    function stakeToken(
        address _token
    ) external view override returns (StakeToken memory) {
        return CPStorage.load().stakeTokens[_token];
    }

    function setStakeAirDrop(
        uint256 _stakeAirDrop
    ) external override onlyPoolManager nonZero(_stakeAirDrop) {
        uint256 oldStakeAirDrop = AirDropStorage.load().stakeAirDrop;
        AirDropStorage.load().stakeAirDrop = _stakeAirDrop;
        emit SetStakeAirDrop(msg.sender, oldStakeAirDrop, _stakeAirDrop);
    }

    function setMaxClaim(
        uint256 _maxClaim
    ) external override onlyPoolManager nonZero(_maxClaim) {
        uint256 oldMaxClaim = AirDropStorage.load().maxClaim;
        AirDropStorage.load().maxClaim = _maxClaim;
        emit SetMaxClaim(msg.sender, oldMaxClaim, _maxClaim);
    }

    function setPaymaster(
        address _paymaster
    ) external override onlyPoolManager positiveAddress(_paymaster) {
        address oldPaymaster = AirDropStorage.load().paymaster;
        AirDropStorage.load().paymaster = _paymaster;
        emit SetPaymaster(msg.sender, oldPaymaster, _paymaster);
    }

    function setMinPoolMaturity(
        uint256 _minPoolMaturity
    ) external override onlyPoolManager {
        uint256 oldMinPoolMaturity = AirDropStorage.load().minPoolMaturity;
        AirDropStorage.load().minPoolMaturity = _minPoolMaturity;
        emit SetMinPoolMaturity(msg.sender, oldMinPoolMaturity, _minPoolMaturity);
    }

}

contracts/modules/ChallengePoolView.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "../interfaces/IChallengePoolView.sol";
import "../interfaces/IChallengePoolHandler.sol";
import "../interfaces/IChallengePoolDispute.sol";
import "../libraries/LibData.sol";

import "../libraries/LibPrice.sol";

import "../utils/ChallengePoolHelpers.sol";

contract ChallengePoolView is IChallengePoolView, ChallengePoolHelpers {
    function challenges(
        uint256 _challengeId
    ) external view override returns (IChallengePoolHandler.Challenge memory) {
        return CPStorage.load().challenges[_challengeId];
    }

    function playerOptionSupply(
        uint256 _challengeId,
        address _player,
        bytes32 _option
    )
        external
        view
        override
        returns (IChallengePoolHandler.PlayerSupply memory)
    {
        return
            CPStorage.load().playerOptionSupply[_challengeId][_player][_option];
    }

    function playerSupply(
        uint256 _challengeId,
        address _player
    )
        external
        view
        override
        returns (IChallengePoolHandler.PlayerSupply memory)
    {
        return CPStorage.load().playerSupply[_challengeId][_player];
    }

    function optionSupply(
        uint256 _challengeId,
        bytes32 _option
    )
        external
        view
        override
        returns (IChallengePoolHandler.OptionSupply memory)
    {
        return CPStorage.load().optionSupply[_challengeId][_option];
    }

    function poolSupply(
        uint256 _challengeId
    ) external view override returns (IChallengePoolHandler.Supply memory) {
        return CPStorage.load().poolSupply[_challengeId];
    }

    function playerDisputes(
        uint256 _challengeId,
        address _player
    ) external view override returns (IChallengePoolDispute.Dispute memory) {
        return CPStorage.load().playerDisputes[_challengeId][_player];
    }

    function optionDisputes(
        uint256 _challengeId,
        bytes32 _option
    ) external view override returns (uint256) {
        return CPStorage.load().optionDisputes[_challengeId][_option];
    }

    function poolDisputes(
        uint256 _challengeId
    ) external view override returns (uint256) {
        return CPStorage.load().poolDisputes[_challengeId];
    }

    function dataRequest(
        bytes32 _requestId
    ) external view override returns (IDataProvider.DataRequest memory) {
        return DPStorage.load().dataRequest[_requestId];
    }

    function requestOptions(
        bytes32 _requestId,
        bytes32 _option
    ) external view override returns (bool) {
        return DPStorage.load().requestOptions[_requestId][_option];
    }

    function price(
        uint256 _challengeId
    )
        external
        view
        override
        validChallenge(_challengeId)
        poolInState(_challengeId, IChallengePoolCommon.ChallengeState.open)
        returns (uint256)
    {
        return CPStorage.load().challenges[_challengeId].basePrice;
    }

    function earlyWithdrawFee(
        uint256 _price
    ) external view override returns (uint256 fee, uint256 feePlusPrice) {
        fee = LibPrice._computeEarlyWithdrawFee(_price);
        feePlusPrice = _price + fee;
    }

    function createFee(
        uint256 _price
    ) external view override returns (uint256 fee, uint256 feePlusPrice) {
        fee = LibPrice._computeCreateFee(_price);
        feePlusPrice = _price + fee;
    }

    function stakeFee(
        uint256 _price
    ) external view override returns (uint256 fee, uint256 feePlusPrice) {
        fee = LibPrice._computeStakeFee(_price);
        feePlusPrice = _price + fee;
    }

    function earlyWithdrawPenalty(
        uint256 _challengeId
    )
        external
        view
        override
        validChallenge(_challengeId)
        returns (uint256 penalty, uint256 priceMinusPenalty)
    {
        IChallengePoolCommon.Challenge storage c = CPStorage.load().challenges[
            _challengeId
        ];
        penalty = LibPrice._penalty(c.basePrice, c.createdAt, c.maturity);
        priceMinusPenalty = c.basePrice - penalty;
    }

    function getAccumulatedFee(address _token) external view returns (uint256) {
        return CPStorage.load().stakeTokens[_token].accumulatedFee;
    }

    function winnerShare(
        uint256 _challengeId,
        address _player
    ) external view override returns (uint256) {
        CPStore storage s = CPStorage.load();
        IChallengePoolHandler.Challenge storage c = s.challenges[_challengeId];
        if (HelpersLib.compareBytes(HelpersLib.emptyBytes, c.outcome)) {
            revert IChallengePoolCommon.InvalidOutcome();
        }
        if (s.optionSupply[_challengeId][keccak256(c.outcome)].rewards == 0) {
            return 0;
        }
        IChallengePoolHandler.PlayerSupply storage playerOption = s
            .playerOptionSupply[_challengeId][_player][keccak256(c.outcome)];
        if (c.state == IChallengePoolCommon.ChallengeState.closed) {
            return
                LibPrice._computeWinnerShare(
                    _challengeId,
                    playerOption.rewards
                );
        } else if (c.state == IChallengePoolCommon.ChallengeState.cancelled) {
            return 0;
        } else {
            revert IChallengePoolCommon.ActionNotAllowedForState(c.state);
        }
    }

    function stakeAirDrop() external view override returns (uint256) {
        return AirDropStorage.load().stakeAirDrop;
    }

    function maxClaim() external view override returns (uint256) {
        return AirDropStorage.load().maxClaim;
    }

    function paymaster() external view override returns (address) {
        return AirDropStorage.load().paymaster;
    }

    function minPoolMaturity() external view override returns (uint256) {
        return AirDropStorage.load().minPoolMaturity;
    }

}

contracts/modules/Community.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "../interfaces/ICommunity.sol";
import "../libraries/LibData.sol";
import "../utils/CommunityHelpers.sol";
import "../utils/Helpers.sol";
import "../diamond/interfaces/SoccersmRoles.sol";
import "../interfaces/IChallengePoolCommon.sol";
import "../utils/ChallengePoolHelpers.sol";
import "../interfaces/IChallengePoolHandler.sol";

contract Community is
    ICommunity,
    CommunityHelpers,
    Helpers,
    SoccersmRoles,
    IChallengePoolCommon,
    ChallengePoolHelpers
{
    function createCommunity(
        string calldata _communityId
    ) external override nonEmptyString(_communityId) {
        CommunityStore storage s = CommunityStorage.load();
        bytes32 communityId = keccak256(bytes(_communityId));
        if (bytes(s.communities[communityId].communityId).length > 0) {
            revert CommunityAlreadyExists();
        }
        s.communities[communityId] = ICommunity.Community({
            communityId: _communityId,
            owner: msg.sender,
            pendingOwner: address(0),
            memberCount: 1,
            banned: false,
            tournamentId: bytes32(0)
        });
        s.isMember[communityId][msg.sender] = true;
        uint256 memberCount = s.communities[communityId].memberCount;
        bool bannedStatus = s.communities[communityId].banned;
        emit NewCommunity(
            _communityId,
            communityId,
            msg.sender,
            memberCount,
            bannedStatus,
            block.timestamp
        );
    }

    function addCommunityAdmin(
        bytes32 _communityId,
        address _admin
    )
        external
        override
        positiveAddress(_admin)
        communityExists(_communityId)
        communityNotBanned(_communityId)
        onlyCommunityOwner(_communityId)
        isCommunityMember(_communityId, _admin)
    {
        CommunityStore storage s = CommunityStorage.load();
        if (s.isAdmin[_communityId][_admin]) {
            revert ICommunity.AlreadyCommunityAdmin();
        }
        s.isAdmin[_communityId][_admin] = true;
        emit AdminAdded(_communityId, msg.sender, _admin);
    }

    function removeCommunityAdmin(
        bytes32 _communityId,
        address _admin
    )
        external
        override
        positiveAddress(_admin)
        communityExists(_communityId)
        communityNotBanned(_communityId)
        onlyCommunityOwner(_communityId)
    {
        CommunityStore storage s = CommunityStorage.load();
        if (!s.isAdmin[_communityId][_admin]) {
            revert MustBeCommunityAdmin();
        }
        delete s.isAdmin[_communityId][_admin];
        emit AdminRemoved(_communityId, msg.sender, _admin);
    }

    function banCommunity(
        bytes32 _communityId
    )
        external
        override
        onlySoccersmCouncil
        communityExists(_communityId)
        communityNotBanned(_communityId)
    {
        CommunityStore storage s = CommunityStorage.load();
        ICommunity.Community storage community = s.communities[_communityId];
        community.banned = true;
        emit CommunityBanned(_communityId, msg.sender, community.banned);
    }

    function unBanCommunity(
        bytes32 _communityId
    )
        external
        override
        onlySoccersmCouncil
        communityExists(_communityId)
        communityBanned(_communityId)
    {
        CommunityStore storage s = CommunityStorage.load();
        ICommunity.Community storage community = s.communities[_communityId];
        community.banned = false;
        emit CommunityUnBanned(_communityId, msg.sender, community.banned);
    }

    function banMember(
        bytes32 _communityId,
        address _user
    )
        external
        virtual
        override
        communityExists(_communityId)
        communityNotBanned(_communityId)
        positiveAddress(_user)
        communityOwnerOrAdmin(_communityId)
        isCommunityMember(_communityId, _user)
    {
        CommunityStore storage s = CommunityStorage.load();
        ICommunity.Community storage community = s.communities[_communityId];
        require(_user != community.owner, "Cannot ban or unban owner");
        s.memberBanned[_communityId][_user] = true;
        if (s.isMember[_communityId][_user]) {
            s.isMember[_communityId][_user] = false;
            if (community.memberCount > 0) {
                community.memberCount -= 1;
            }
        }
        emit MemberIsBanned(
            _communityId,
            _user,
            community.memberCount,
            block.timestamp
        );
    }

    function unBanMember(
        bytes32 _communityId,
        address _user
    )
        external
        virtual
        override
        communityExists(_communityId)
        communityNotBanned(_communityId)
        positiveAddress(_user)
        communityOwnerOrAdmin(_communityId)
    {
        CommunityStore storage s = CommunityStorage.load();
        ICommunity.Community storage community = s.communities[_communityId];
        require(_user != community.owner, "Cannot ban or unban owner");
        require(s.memberBanned[_communityId][_user], "Member must be banned");
        s.memberBanned[_communityId][_user] = false;
        emit MemberUnbanned(_communityId, _user, block.timestamp);
    }

    function joinCommunity(
        bytes32 _communityId
    )
        external
        override
        communityExists(_communityId)
        communityNotBanned(_communityId)
    {
        CommunityStore storage s = CommunityStorage.load();
        ICommunity.Community storage community = s.communities[_communityId];
        require(!s.memberBanned[_communityId][msg.sender], "Member is banned");
        if (s.isMember[_communityId][msg.sender]) {
            revert AlreadyCommunityMember();
        }
        s.isMember[_communityId][msg.sender] = true;
        community.memberCount += 1;
        emit MemberJoined(
            _communityId,
            msg.sender,
            community.memberCount,
            block.timestamp
        );
    }

    function leaveCommunity(
        bytes32 _communityId
    )
        external
        override
        communityExists(_communityId)
        communityNotBanned(_communityId)
    {
        CommunityStore storage s = CommunityStorage.load();
        ICommunity.Community storage community = s.communities[_communityId];
        require(msg.sender != community.owner, "Owner cannot leave community");
        require(s.isMember[_communityId][msg.sender], "Must be a member");
        if (s.isAdmin[_communityId][msg.sender]) {
            delete s.isAdmin[_communityId][msg.sender];
        }
        delete s.isMember[_communityId][msg.sender];
        if (community.memberCount > 0) {
            community.memberCount -= 1;
        }
        emit MemberLeftCommunity(
            _communityId,
            msg.sender,
            community.memberCount,
            block.timestamp
        );
    }

    function removeCommunityMember(
        bytes32 _communityId,
        address _member
    )
        external
        override
        positiveAddress(_member)
        communityExists(_communityId)
        communityNotBanned(_communityId)
        isCommunityMember(_communityId, _member)
        communityOwnerOrAdmin(_communityId)
    {
        CommunityStore storage s = CommunityStorage.load();
        ICommunity.Community storage community = s.communities[_communityId];
        require(_member != community.owner, "Cannot remove owner");
        require(!s.isAdmin[_communityId][_member], "Cannot remove admin");
        delete s.isMember[_communityId][_member];
        if (community.memberCount > 0) {
            community.memberCount -= 1;
        }
        emit MemberRemoved(
            _communityId,
            _member,
            community.memberCount,
            block.timestamp
        );
    }

    function transferCommunityOwner(
        bytes32 _communityId,
        address _newOwner
    )
        external
        override
        positiveAddress(_newOwner)
        communityExists(_communityId)
        onlyCommunityOwner(_communityId)
        isCommunityMember(_communityId, _newOwner)
    {
        CommunityStore storage s = CommunityStorage.load();
        ICommunity.Community storage community = s.communities[_communityId];
        require(
            _newOwner != msg.sender,
            "Cannot initiate transfer to current owner"
        );
        community.pendingOwner = _newOwner;
        emit CommunityOwnerTransferInitiated(
            _communityId,
            msg.sender,
            _newOwner,
            block.timestamp
        );
    }

    function acceptCommunityOwnership(
        bytes32 _communityId
    ) external override communityExists(_communityId) {
        CommunityStore storage s = CommunityStorage.load();
        ICommunity.Community storage community = s.communities[_communityId];
        require(msg.sender == community.pendingOwner, "Not pending owner");
        address previousOwner = community.owner;
        community.owner = msg.sender;
        delete community.pendingOwner;
        emit CommunityOwnerTransferAccepted(
            _communityId,
            previousOwner,
            msg.sender,
            block.timestamp
        );
    }

     function evaluateCustomChallenge(
        uint256 _challengeId,
        bytes memory _results
    ) external override poolInState(_challengeId, ChallengeState.matured) {
        CommunityStore storage cs = CommunityStorage.load();
        CPStore storage s = CPStorage.load();
        IChallengePool.Challenge storage challenge = s.challenges[_challengeId];
        bytes32 communityId = challenge.communityId;
        ICommunity.Community storage community = cs.communities[communityId];
        if (challenge.cType != ChallengeType.community) {
            revert CommunityChallengeRequiresCommunity();
        }
        if (community.owner == address(0)) {
            revert CommunityDoesNotExist(communityId);
        }
        if (community.banned) {
            revert CommunityIsBanned();
        }

        if (
            !cs.isAdmin[communityId][msg.sender] &&
            community.owner != msg.sender
        ) {
            revert NotCommunityOwnerOrAdmin(communityId, msg.sender);
        }
        challenge.outcome = _results;
        challenge.lastOutcomeSet = block.timestamp;
        challenge.state = ChallengeState.evaluated;
        emit IChallengePoolHandler.EvaluateChallenge(
            _challengeId,
            msg.sender,
            ChallengeState.evaluated,
            _results
        );
    }
}

