// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "./BaseProvider.sol";

contract AssetPriceDataProvider is BaseProvider {
    function requestData(
        bytes calldata _params
    ) external override returns (bool) {
        (string memory assetSymbol, uint256 date) = _decodeRequestedParams(
            _params
        );

        bytes32 requestId = _requestId(assetSymbol, date);

        if (requestExists(requestId)) {
            return true;
        }

        DPStore storage d = DPStorage.load();

        d.dataRequest[requestId] = DataRequest(_params, HelpersLib.emptyBytes, false);

        emit DataRequested(msg.sender, namespace(), requestId, _params);
        return true;
    }

    function _provideData(
        bytes calldata _params,
        ProvisionMode _mode
    ) internal override {
        (
            string memory assetSymbol,
            uint256 date,
            uint256 price
        ) = _decodeProvidedParams(_params);
        if (block.timestamp < date) {
            revert InvalidSubmissionDate(date);
        }

        bytes32 requestId = _requestId(assetSymbol, date);

        if (!requestExists(requestId)) {
            revert DataNotRequested();
        }

        if (dataExists(requestId) && _mode == ProvisionMode.create) {
            revert DataAlreadyProvided();
        }

        DPStore storage d = DPStorage.load();

        d.dataRequest[requestId].provided = abi.encode(price);

        emit DataProvided(
            msg.sender,
            namespace(),
            requestId,
            d.dataRequest[requestId].provided
        );
    }

    function _requestId(
        string memory assetSymbol,
        uint256 date
    ) internal pure returns (bytes32) {
        return keccak256(abi.encode(namespace(), assetSymbol, date));
    }

    function _decodeRequestedParams(
        bytes calldata _params
    ) internal pure returns (string memory, uint256) {
        return abi.decode(_params, (string, uint256));
    }

    function _decodeProvidedParams(
        bytes calldata _params
    ) internal pure returns (string memory, uint256, uint256) {
        return abi.decode(_params, (string, uint256, uint256));
    }

    function _requestIdFromParams(
        bytes calldata _params
    ) internal pure virtual override returns (bytes32) {
        (string memory assetSymbol, uint256 date) = _decodeRequestedParams(
            _params
        );
        return _requestId(assetSymbol, date);
    }

    function namespace() public pure override returns (string memory) {
        return "asset-price";
    }
}

contracts/modules/data-providers/BasePro.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "../../interfaces/IDataProvider.sol";
import "../../libraries/LibData.sol";
import "../../utils/Helpers.sol";

import "../../utils/Errors.sol";

abstract contract BaseProvider is IDataProvider {
    enum ProvisionMode {
        create,
        update
    }
    function _requestIdFromParams(
        bytes calldata _params
    ) internal pure virtual returns (bytes32);
    function requestExists(
        bytes32 requestId
    ) internal view returns (bool) {
        DPStore storage d = DPStorage.load();
        bool requestEmpty = HelpersLib.compareBytes(
            d.dataRequest[requestId].requested,
            HelpersLib.emptyBytes
        );
        bool isRegister = d.dataRequest[requestId].register;
        return !requestEmpty && !isRegister;
    }

    function dataExists(bytes32 requestId) internal view returns (bool) {
        DPStore storage d = DPStorage.load();
        return
            !HelpersLib.compareBytes(
                d.dataRequest[requestId].provided,
                HelpersLib.emptyBytes
            );
    }

    function registerExists(
        bytes32 requestId
    ) internal view returns (bool) {
        DPStore storage d = DPStorage.load();
        return d.dataRequest[requestId].register;
    }

    function registerEvent(bytes calldata /*_params*/) external virtual {
        revert NotImplemented();
    }

    function validateOptions(
        bytes calldata /*_params*/,
        bytes[] calldata _options
    ) external virtual returns (bool) {
        return _options.length > 1;
    }

    function getData(
        bytes calldata _params
    ) external view override returns (bytes memory _data) {
        bytes32 requestId = _requestIdFromParams(_params);
        if (!dataExists(requestId)) {
            revert DataNotProvided();
        }
        DPStore storage d = DPStorage.load();

        return d.dataRequest[requestId].provided;
    }

    function hasData(
        bytes calldata _params
    ) external view override returns (bool) {
        return dataExists(_requestIdFromParams(_params));
    }

    function _provideData(
        bytes calldata _params,
        ProvisionMode _mode
    ) internal virtual;

    function provideData(bytes calldata _params) external override {
        _provideData(_params, ProvisionMode.create);
    }

    function updateProvision(bytes calldata _params) external override {
        _provideData(_params, ProvisionMode.update);
    }
}

