// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;
import "../interfaces/IChallengePoolCommon.sol";
import "../libraries/LibData.sol";
import "../libraries/LibPool.sol";
abstract contract ChallengePoolHelpers {
    modifier validChallenge(uint256 _challengeId) {
        if (_challengeId >= CPStorage.load().challengeId) {
            revert IChallengePoolCommon.InvalidChallenge();
        }
        _;
    }

    modifier poolInState(
        uint256 _challengeId,
        IChallengePoolCommon.ChallengeState _state
    ) {
        IChallengePoolCommon.ChallengeState currentState = LibPool._poolState(
            CPStorage.load().challenges[_challengeId]
        );
        if (currentState != _state) {
            revert IChallengePoolCommon.ActionNotAllowedForState(currentState);
        }
        _;
    }

    modifier validStake(uint256 _stake) {
        if (_stake < CPStorage.load().minStakeAmount) {
            revert IChallengePoolCommon.StakeLowerThanMinimum();
        }
        _;
    }

    modifier validPrediction(bytes memory _prediction) {
        if (HelpersLib.compareBytes(_prediction, HelpersLib.emptyBytes)) {
            revert IChallengePoolCommon.InvalidPrediction();
        }
        _;
    }

    modifier supportedToken(address _token) {
        if (!CPStorage.load().stakeTokens[_token].active) {
            revert IChallengePoolCommon.UnsupportedToken(_token);
        }
        _;
    }
}

contracts/utils/CommunityHelpers.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "../interfaces/ICommunity.sol";
import "../libraries/LibData.sol";

abstract contract CommunityHelpers {
    modifier communityNotBanned(bytes32 _communityId) {
        CommunityStore storage s = CommunityStorage.load();
        ICommunity.Community storage community = s.communities[_communityId];
        if (community.banned) {
            revert ICommunity.CommunityIsBanned();
        }
        _;
    }

    modifier communityBanned(bytes32 _communityId) {
        CommunityStore storage s = CommunityStorage.load();
        ICommunity.Community storage community = s.communities[_communityId];
        if (!community.banned) {
            revert ICommunity.CommunityNotBanned();
        }
        _;
    }

    modifier onlyCommunityOwner(bytes32 _communityId) {
        CommunityStore storage s = CommunityStorage.load();
        ICommunity.Community storage community = s.communities[_communityId];
        if (msg.sender != s.communities[_communityId].owner) {
            revert ICommunity.NotCommunityOwner();
        }
        _;
    }

    modifier communityOwnerOrAdmin(bytes32 _communityId) {
        CommunityStore storage s = CommunityStorage.load();
        ICommunity.Community storage community = s.communities[_communityId];

        if (msg.sender == community.owner) {
            _;
            return;
        }

        if (!s.isAdmin[_communityId][msg.sender]) {
            revert ICommunity.NotCommunityOwnerOrAdmin(
                _communityId,
                msg.sender
            );
        }
        _;
    }

    modifier isCommunityMember(bytes32 _communityId, address _member) {
        CommunityStore storage s = CommunityStorage.load();
        if (!s.isMember[_communityId][_member]) {
            revert ICommunity.NotCommunityMember();
        }
        _;
    }

    modifier communityExists(bytes32 _communityId) {
        CommunityStore storage s = CommunityStorage.load();
        if (s.communities[_communityId].owner == address(0)) {
            revert ICommunity.CommunityDoesNotExist(_communityId);
        }
        _;
    }
}

